#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int a, b, w;
} Edge;

int find(int *parent, int x) {
    if (parent[x] != x) parent[x] = find(parent, parent[x]);
    return parent[x];
}

void unite(int *parent, int x, int y) {
    int rx = find(parent, x);
    int ry = find(parent, y);
    if (rx != ry) parent[rx] = ry;
}

int cmp_edge(const void *p1, const void *p2) {
    const Edge *e1 = (const Edge *)p1;
    const Edge *e2 = (const Edge *)p2;
    return e1->w - e2->w;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("INVALID_ARGS");
        return 0;
    }
    char *endptr;
    long nEdges = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || nEdges < 0 || nEdges > 9) {
        puts("INVALID_ARGS");
        return 0;
    }
    Edge edges[9];
    for (int i = 0; i < nEdges; ++i) {
        if (scanf("%d %d %d", &edges[i].a, &edges[i].b, &edges[i].w) != 3) {
            puts("INVALID_ARGS");
            return 0;
        }
    }
    // Fixed number of vertices (0..5)
    const int V = 6;
    int parent[V];
    for (int i = 0; i < V; ++i) parent[i] = i;

    // Sort edges by weight (stable)
    qsort(edges, nEdges, sizeof(Edge), cmp_edge);

    int mst_edges = 0;
    int total_weight = 0;
    Edge selected[5];
    for (int i = 0; i < nEdges && mst_edges < V-1; ++i) {
        int ra = find(parent, edges[i].a);
        int rb = find(parent, edges[i].b);
        if (ra != rb) {
            unite(parent, ra, rb);
            selected[mst_edges] = edges[i];
            total_weight += edges[i].w;
            ++mst_edges;
        }
    }
    if (mst_edges != V-1) {
        puts("DISCONNECTED");
        return 0;
    }
    printf("weight=%d edges=", total_weight);
    for (int i = 0; i < mst_edges; ++i) {
        if (i) putchar(',');
        printf("%d-%d", selected[i].a, selected[i].b);
    }
    putchar('\n');
    return 0;
}
}
